1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	import org.springframework.samples.petclinic.util.E164PhoneNumbers;
12	import org.springframework.samples.petclinic.util.IdentityKeyUtils;
13	
14	import java.time.LocalDate;
15	import java.time.Month;
16	import java.time.Period;
17	import java.util.Collection;
18	import java.util.List;
19	import java.util.Map;
20	
21	/**
22	 * Maps Owner & OwnerDto using Mapstruct
23	 */
24	@Mapper(uses = PetMapper.class)
25	public interface OwnerMapper {
26	
27	    @Mapping(target = "displayName",
28	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
29	    @Mapping(target = "initials",
30	        expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" "
31	            + "+ owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
32	    @Mapping(target = "membershipPoints",
33	        expression = "java(toMembershipPoints(owner))")
34	    @Mapping(target = "membershipLevel",
35	        expression = "java(toMembershipLevel(owner))")
36	    @Mapping(target = "locality",
37	        expression = "java(toLocality(owner))")
38	    @Mapping(target = "ownerSegment",
39	        expression = "java(toOwnerSegment(owner))")
40	    @Mapping(target = "timezone",
41	        expression = "java(toTimezone(owner))")
42	    @Mapping(target = "contactPreference",
43	        expression = "java(toContactPreference(owner))")
44	    @Mapping(target = "identityKey",
45	        expression = "java(toIdentityKey(owner))")
46	    @Mapping(target = "ageBand",
47	        expression = "java(toAgeBand(owner))")
48	    @Mapping(target = "telephoneDisplay",
49	        expression = "java(toTelephoneDisplay(owner))")
50	    @Mapping(target = "salutation",
51	        expression = "java(toSalutation(owner))")
52	    @Mapping(target = "fiscalYear",
53	        expression = "java(toFiscalYear(owner))")
54	    @Mapping(target = "selfLink",
55	        expression = "java(toSelfLink(owner))")
56	    OwnerDto toOwnerDto(Owner owner);
57	
58	    /**
59	     * Derive an owner's canonical self link: the resource path {@code '/api/owners/<id>'} where
60	     * {@code <id>} is the owner's id. Returns {@code null} when the owner has no id yet (the field is
61	     * then absent from the DTO).
62	     */
63	    default String toSelfLink(Owner owner) {
64	        return owner.getId() == null ? null : "/api/owners/" + owner.getId();
65	    }
66	
67	    /**
68	     * The fiscal year that the given date falls in, where the fiscal year starts on 1 July and is
69	     * identified by the calendar year in which it ends. A date on or after 1 July belongs to the
70	     * fiscal year ending in the following calendar year (e.g. 2026-08-01 -&gt; 2027), while a date
71	     * before 1 July belongs to the fiscal year ending in the same calendar year (e.g. 2026-03-01 -&gt;
72	     * 2026). This is the single source of truth for the fiscal year used by both the DTO's
73	     * {@code fiscalYear} and the create endpoint's membership-number year segment.
74	     *
75	     * @param date the date to resolve, on a business day
76	     * @return the calendar year in which that date's fiscal year ends
77	     */
78	    static int fiscalYear(LocalDate date) {
79	        int year = date.getYear();
80	        return date.getMonthValue() >= Month.JULY.getValue() ? year + 1 : year;
81	    }
82	
83	    /**
84	     * Derive an owner's fiscal year, formatted {@code 'FY<YY>'} where YY is the two-digit fiscal-year
85	     * segment carried by the {@code memberId} (see {@link #memberIdBase(String)}), e.g. {@code 'FY27'}.
86	     * The fiscal year therefore moves with the owner's member id. When an owner has no (well-formed)
87	     * member id yet (e.g. legacy records) it falls back to deriving the fiscal year directly from the
88	     * business-day-adjusted {@code registrationDate} (see {@link #fiscalYear(LocalDate)}), and returns
89	     * {@code null} when neither is present (the field is then absent from the DTO).
90	     */
91	    default String toFiscalYear(Owner owner) {
92	        String base = memberIdBase(owner.getMemberId());
93	        if (base != null) {
94	            return "FY" + base.substring(base.length() - 11, base.length() - 9);
95	        }
96	        LocalDate registrationDate = owner.getRegistrationDate();
97	        return registrationDate == null ? null : String.format("FY%02d", fiscalYear(registrationDate) % 100);
98	    }
99	
100	    /**
101	     * Derive an owner's salutation: the {@code title}, a single space, and the {@code lastName}
102	     * (e.g. {@code "DR Franklin"}). When no title was supplied (null or blank) the salutation is
103	     * just the last name.
104	     */
105	    default String toSalutation(Owner owner) {
106	        String lastName = owner.getLastName();
107	        String title = owner.getTitle();
108	        if (title == null || title.isBlank()) {
109	            return lastName;
110	        }
111	        return title + " " + lastName;
112	    }
113	
114	    /**
115	     * Derive an owner's age band from the {@code birthDate} relative to the {@code registrationDate}:
116	     * 'MINOR' when under 18, 'ADULT' when 18 to 64, and 'SENIOR' when 65 or older. Returns
117	     * {@code null} when no birth date was supplied (the band is then absent from the DTO). When the
118	     * registration date is missing (e.g. legacy records) the current date is used as the reference.
119	     */
120	    default OwnerDto.AgeBandEnum toAgeBand(Owner owner) {
121	        LocalDate birthDate = owner.getBirthDate();
122	        if (birthDate == null) {
123	            return null;
124	        }
125	        LocalDate reference = owner.getRegistrationDate() != null
126	            ? owner.getRegistrationDate() : LocalDate.now();
127	        int age = Period.between(birthDate, reference).getYears();
128	        if (age < 18) {
129	            return OwnerDto.AgeBandEnum.MINOR;
130	        }
131	        if (age < 65) {
132	            return OwnerDto.AgeBandEnum.ADULT;
133	        }
134	        return OwnerDto.AgeBandEnum.SENIOR;
135	    }
136	
137	    /**
138	     * Format an owner's stored E.164 {@code telephone} for humans: the country code, a space, then the
139	     * national digits grouped in threes (e.g. {@code "+61412345678"} becomes {@code "+61 412 345 678"}).
140	     * The raw {@code telephone} property is left untouched in E.164 form. Returns the value unchanged
141	     * when it is {@code null} or not in {@code '+'}-prefixed E.164 form.
142	     *
143	     * <p>The recognized dialling codes come from {@link E164PhoneNumbers}, the same table the create
144	     * endpoint validates against, so the two paths cannot diverge. When a number carries no recognized
145	     * code, a two-digit country code is assumed (the most common length).
146	     */
147	    default String toTelephoneDisplay(Owner owner) {
148	        String telephone = owner.getTelephone();
149	        if (telephone == null || !telephone.startsWith("+")) {
150	            return telephone;
151	        }
152	        String digits = telephone.substring(1);
153	        String code = E164PhoneNumbers.countryCode(digits)
154	            .filter(c -> digits.length() > c.length())
155	            .orElse(digits.length() > 2 ? digits.substring(0, 2) : digits);
156	        String national = digits.substring(code.length());
157	        StringBuilder sb = new StringBuilder("+").append(code);
158	        for (int i = 0; i < national.length(); i += 3) {
159	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
160	        }
161	        return sb.toString();
162	    }
163	
164	    /**
165	     * The {@code '<REGION><FY><HASH8><CHK>'} base of a member id, dropping any {@code '-<n>'} collision
166	     * suffix, or {@code null} when the owner has no (well-formed) member id yet. The trailing segments
167	     * have fixed widths — FY (2 digits), HASH8 (8 hex) and CHK (1 digit) — so REGION and FY can be
168	     * recovered from the base by position: REGION is everything before the trailing 11 characters and
169	     * FY is the two characters immediately preceding HASH8 and CHK.
170	     */
171	    private static String memberIdBase(String memberId) {
172	        if (memberId == null) {
173	            return null;
174	        }
175	        int dash = memberId.indexOf('-');
176	        String base = dash >= 0 ? memberId.substring(0, dash) : memberId;
177	        // A well-formed base is REGION (>= 1 char) + FY (2) + HASH8 (8) + CHK (1) = > 11 characters.
178	        return base.length() > 11 ? base : null;
179	    }
180	
181	    /**
182	     * Derive an owner's duplicate-detection identity key: the lower-case SHA-256 hex digest (64
183	     * characters) of the normalized E.164 telephone, the lower-cased email (empty when none) and the
184	     * American Soundex code of the last name, joined with {@code '|'}. Two owners are duplicates only
185	     * when their whole identity keys are equal.
186	     *
187	     * <p>This is the single source of truth for the key: it is both returned on the DTO and used by
188	     * the create endpoint's 409 duplicate check, so the value clients see is exactly the value that
189	     * governs rejection. The "email present" rule reuses {@link #hasEmail(Owner)}, and the Soundex and
190	     * hashing come from {@link IdentityKeyUtils}, the same helpers the soft-match uses.
191	     */
192	    default String toIdentityKey(Owner owner) {
193	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
194	        String email = hasEmail(owner) ? owner.getEmail() : "";
195	        String soundex = IdentityKeyUtils.soundex(owner.getLastName());
196	        return IdentityKeyUtils.sha256Hex(telephone + "|" + email + "|" + soundex);
197	    }
198	
199	    /**
200	     * Whether the owner has an email address present (non-null and non-empty). Single source of truth
201	     * for the "is an email present" rule shared by the derived fields below.
202	     */
203	    default boolean hasEmail(Owner owner) {
204	        return owner.getEmail() != null && !owner.getEmail().isEmpty();
205	    }
206	
207	    /**
208	     * Derive an owner's preferred contact channel: 'EMAIL' when an email address is present,
209	     * otherwise 'PHONE'.
210	     */
211	    default String toContactPreference(Owner owner) {
212	        return hasEmail(owner) ? "EMAIL" : "PHONE";
213	    }
214	
215	    /**
216	     * Derive an owner's membership points: start at 0; add 2 when an email address is present; add 1
217	     * when the owner has no namesakes (namesakeCount is 0); add 2 when the owner belongs to a
218	     * household of 3 or more (see {@link #hasHouseholdBonus(Owner)}); add 3 when the owner's tenure
219	     * is at least one elapsed fiscal year (see {@link #hasTenureBonus(Owner)}). Because a newly
220	     * created owner has zero tenure it never earns the tenure points, so a new owner with an email
221	     * and no namesakes in a single-member household scores 3 points.
222	     */
223	    default Integer toMembershipPoints(Owner owner) {
224	        int points = 0;
225	        if (hasEmail(owner)) {
226	            points += 2;
227	        }
228	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
229	        if (noNamesakes) {
230	            points += 1;
231	        }
232	        if (hasHouseholdBonus(owner)) {
233	            points += 2;
234	        }
235	        if (hasTenureBonus(owner)) {
236	            points += 3;
237	        }
238	        return points;
239	    }
240	
241	    /**
242	     * Whether the owner belongs to a household of 3 or more members. The household size is the count
243	     * of owners sharing the owner's household id, frozen at creation (see the create endpoint).
244	     * Returns {@code false} when no household size is present (e.g. legacy records).
245	     */
246	    default boolean hasHouseholdBonus(Owner owner) {
247	        return owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3;
248	    }
249	
250	    /**
251	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
252	     * {@link #toMembershipPoints(Owner)}): level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6
253	     * or more.
254	     *
255	     * <p>The level is then capped at the owner's {@code membershipLevelCap} when one is present: a new
256	     * owner's membership level cannot exceed one above the current maximum membership level among their
257	     * existing household members, so the cap (frozen at creation, see the create endpoint) is the
258	     * ceiling applied here. When no cap is present (e.g. an owner created with no existing household
259	     * member, or a legacy record) the uncapped level stands.
260	     */
261	    default Integer toMembershipLevel(Owner owner) {
262	        int level = uncappedMembershipLevel(owner);
263	        Integer cap = owner.getMembershipLevelCap();
264	        if (cap != null && level > cap) {
265	            return cap;
266	        }
267	        return level;
268	    }
269	
270	    /**
271	     * Derive an owner's numeric membership level (1 to 4) from its membership points (see
272	     * {@link #toMembershipPoints(Owner)}) before any household ceiling is applied: level 1 for 0-1
273	     * points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more.
274	     */
275	    default Integer uncappedMembershipLevel(Owner owner) {
276	        int points = toMembershipPoints(owner);
277	        if (points <= 1) {
278	            return 1;
279	        }
280	        if (points <= 3) {
281	            return 2;
282	        }
283	        if (points <= 5) {
284	            return 3;
285	        }
286	        return 4;
287	    }
288	
289	    /**
290	     * Whether the owner's tenure is at least one elapsed fiscal year, i.e. the fiscal year of the
291	     * current date is later than the fiscal year of the {@code registrationDate} (fiscal years start
292	     * on 1 July; see {@link #fiscalYear(LocalDate)}). A brand-new owner (registered in the current
293	     * fiscal year) has zero elapsed fiscal years and so never qualifies. Returns {@code false} when
294	     * no registration date is present.
295	     */
296	    default boolean hasTenureBonus(Owner owner) {
297	        LocalDate registrationDate = owner.getRegistrationDate();
298	        if (registrationDate == null) {
299	            return false;
300	        }
301	        return fiscalYear(LocalDate.now()) - fiscalYear(registrationDate) >= 1;
302	    }
303	
304	    /**
305	     * Fixed city-to-region table used as the fall-back when deriving an owner's locality.
306	     */
307	    Map<String, String> CITY_REGION = Map.of(
308	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
309	
310	    /**
311	     * Fixed region-to-inclusive-postcode-range table used to derive an owner's locality from the
312	     * postcode: NSW 2000-2099, VIC 3000-3099, QLD 4000-4099. Each entry is {@code {low, high}}
313	     * inclusive.
314	     */
315	    Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
316	        "NSW", new int[] {2000, 2099},
317	        "VIC", new int[] {3000, 3099},
318	        "QLD", new int[] {4000, 4099});
319	
320	    /**
321	     * Derive an owner's locality (region) from the region-and-hash member id: the leading
322	     * {@code <REGION>} segment of the {@code memberId}, i.e. everything before its trailing FY, HASH8
323	     * and CHK segments (see {@link #memberIdBase(String)}). Since the region is baked into the member id
324	     * at creation (see the create endpoint), the locality now moves with that identity rather than being
325	     * recomputed from the postcode and city. When an owner has no (well-formed) member id yet (e.g.
326	     * legacy records), fall back to deriving the region directly via {@link #regionOf(Owner)}.
327	     */
328	    default String toLocality(Owner owner) {
329	        String base = memberIdBase(owner.getMemberId());
330	        if (base != null) {
331	            return base.substring(0, base.length() - 11);
332	        }
333	        return regionOf(owner);
334	    }
335	
336	    /**
337	     * Derive an owner's marketing segment, formatted {@code '<TIER>_<AREA>'} and one of
338	     * {@code 'PREMIUM_METRO'}, {@code 'PREMIUM_REGIONAL'}, {@code 'STANDARD_METRO'} or
339	     * {@code 'STANDARD_REGIONAL'}. TIER is {@code 'PREMIUM'} when the owner's membership level (see
340	     * {@link #toMembershipLevel(Owner)}) is 3 or more, otherwise {@code 'STANDARD'}. AREA is
341	     * {@code 'METRO'} when the owner's locality (see {@link #toLocality(Owner)}) is a known region
342	     * (NSW, VIC or QLD, i.e. one carrying a {@link #REGION_TIMEZONE} entry), otherwise
343	     * {@code 'REGIONAL'}.
344	     */
345	    default String toOwnerSegment(Owner owner) {
346	        String tier = toMembershipLevel(owner) >= 3 ? "PREMIUM" : "STANDARD";
347	        String area = REGION_TIMEZONE.containsKey(toLocality(owner)) ? "METRO" : "REGIONAL";
348	        return tier + "_" + area;
349	    }
350	
351	    /**
352	     * Fixed region-to-IANA-timezone table used to derive an owner's timezone: NSW -> Australia/Sydney,
353	     * VIC -> Australia/Melbourne, QLD -> Australia/Brisbane.
354	     */
355	    Map<String, String> REGION_TIMEZONE = Map.of(
356	        "NSW", "Australia/Sydney",
357	        "VIC", "Australia/Melbourne",
358	        "QLD", "Australia/Brisbane");
359	
360	    /**
361	     * Derive an owner's IANA timezone name from its locality/region (see {@link #toLocality(Owner)})
362	     * via the fixed {@link #REGION_TIMEZONE} table. Returns {@code null} when the region resolves to no
363	     * entry in the table (e.g. 'UNKNOWN'), so the timezone is then absent from the DTO.
364	     */
365	    default String toTimezone(Owner owner) {
366	        return REGION_TIMEZONE.get(toLocality(owner));
367	    }
368	
369	    /**
370	     * Derive an owner's region, preferring the postcode: when the postcode is present and falls within
371	     * a known region's range (see {@link #REGION_POSTCODE_RANGES}) that region wins. When the postcode
372	     * is absent or in no known range, fall back to the fixed {@link #CITY_REGION} table. Returns
373	     * 'UNKNOWN' when neither the postcode nor the city resolves a region. This is the region baked into
374	     * the leading {@code <REGION>} segment of a new owner's member id and, through it, the owner's
375	     * locality.
376	     */
377	    default String regionOf(Owner owner) {
378	        // Prefer the postcode: the region whose range contains it wins. The logic is kept here (rather
379	        // than in a String -> String helper) because MapStruct would treat such a helper as an implicit
380	        // type conversion and wrongly apply it to other String properties (e.g. telephone).
381	        String postcode = owner.getPostcode();
382	        if (postcode != null) {
383	            try {
384	                int value = Integer.parseInt(postcode.trim());
385	                for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
386	                    int[] range = entry.getValue();
387	                    if (value >= range[0] && value <= range[1]) {
388	                        return entry.getKey();
389	                    }
390	                }
391	            }
392	            catch (NumberFormatException ignored) {
393	                // Non-numeric postcode: fall back to the city table below.
394	            }
395	        }
396	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
397	    }
398	
399	    Owner toOwner(OwnerDto ownerDto);
400	
401	    @Mapping(target = "id", ignore = true)
402	    @Mapping(target = "pets", ignore = true)
403	    Owner toOwner(OwnerFieldsDto ownerDto);
404	
405	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
406	
407	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
408	
409	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
410	        OwnerPageDto ownerPageDto = new OwnerPageDto();
411	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
412	        ownerPageDto.setPage(ownerPage.getNumber());
413	        ownerPageDto.setSize(ownerPage.getSize());
414	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
415	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
416	        return ownerPageDto;
417	    }
418	}
