29	import org.slf4j.Logger;
30	import org.slf4j.LoggerFactory;
31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.samples.petclinic.util.E164PhoneNumbers;
49	import org.springframework.samples.petclinic.util.IdentityKeyUtils;
50	import org.springframework.security.access.prepost.PreAuthorize;
51	import org.springframework.web.bind.annotation.CrossOrigin;
52	import org.springframework.web.bind.annotation.RequestMapping;
53	import org.springframework.web.bind.annotation.RestController;
54	import org.springframework.web.server.ResponseStatusException;
55	import org.springframework.web.util.UriComponentsBuilder;
56	
57	import jakarta.servlet.http.HttpServletRequest;
58	import jakarta.transaction.Transactional;
59	
60	/**
61	 * @author Vitaliy Fedoriv
62	 */
63	
64	@RestController
65	@CrossOrigin(exposedHeaders = "errors, content-type")
66	@RequestMapping("/api")
67	public class OwnerRestControllerV1 implements OwnersApi {
68	
69	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
70	
71	    /**
72	     * Assigns the monotonically increasing sequence number carried by each structured
73	     * {@link OwnerCreatedEvent}. Static so the order spans every create handled by this endpoint,
74	     * regardless of the controller instance, giving the audit event stream a total order.
75	     */
76	    private static final AtomicLong AUDIT_EVENT_SEQUENCE = new AtomicLong();
77	
78	    private final ClinicService clinicService;
79	
80	    private final OwnerMapper ownerMapper;
81	
82	    private final PetMapper petMapper;
83	
84	    private final VisitMapper visitMapper;
85	
86	    private final IdempotencyKeyRegistry idempotencyKeyRegistry;
87	
88	    private final HttpServletRequest request;
89	
90	    /** HTTP header carrying the idempotency key for the create-owner endpoint. */
91	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
92	
93	    public OwnerRestControllerV1(ClinicService clinicService,
94	                                 OwnerMapper ownerMapper,
95	                                 PetMapper petMapper,
96	                                 VisitMapper visitMapper,
97	                                 IdempotencyKeyRegistry idempotencyKeyRegistry,
98	                                 HttpServletRequest request) {
99	        this.clinicService = clinicService;
100	        this.ownerMapper = ownerMapper;
101	        this.petMapper = petMapper;
102	        this.visitMapper = visitMapper;
103	        this.idempotencyKeyRegistry = idempotencyKeyRegistry;
104	        this.request = request;
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
110	        Collection<Owner> owners;
111	        if (lastName != null) {
112	            owners = this.clinicService.findOwnerByLastName(lastName);
113	        } else {
114	            owners = this.clinicService.findAllOwners();
115	        }
116	        if (owners.isEmpty()) {
117	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
118	        }
119	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
125	        Owner owner = this.clinicService.findOwnerById(ownerId);
126	        if (owner == null) {
127	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
128	        }
129	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
130	    }
131	
132	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
133	    @Override
134	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
135	        HttpHeaders headers = new HttpHeaders();
136	        String idempotencyKey = this.request.getHeader(IDEMPOTENCY_KEY_HEADER);
137	        Integer existingId = this.idempotencyKeyRegistry.findOwnerId(idempotencyKey);
138	        if (existingId != null) {
139	            Owner existing = this.clinicService.findOwnerById(existingId);
140	            if (existing != null) {
141	                return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
142	            }
143	        }
144	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
145	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
146	        owner.setTelephone(normalizedTelephone);
147	        owner.setEmail(normalizeEmail(owner.getEmail()));
148	        applyAddress(owner);
149	        validatePostcode(owner.getCity(), owner.getPostcode());
150	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
151	        if (effectiveRegistrationDate == null) {
152	            effectiveRegistrationDate = LocalDate.now();
153	        } else if (effectiveRegistrationDate.isAfter(LocalDate.now())) {
154	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
155	                "registrationDate must not be later than the current server date");
156	        }
157	        effectiveRegistrationDate = rollToBusinessDay(effectiveRegistrationDate);
158	        owner.setRegistrationDate(effectiveRegistrationDate);
159	        if (countOwnersRegisteredOn(effectiveRegistrationDate) >= DAILY_CREATE_LIMIT) {
160	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
161	                "the maximum number of owners that may be created today has been reached");
162	        }
163	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
164	        // The household id is deterministic (derived from the last name and postcode), so every
165	        // owner is keyed to its household automatically, regardless of creation order.
166	        this.clinicService.assignHousehold(owner);
167	        // An owner joining an existing household is now admitted rather than rejected; their
168	        // membership level is instead capped relative to the household (see the level-ceiling rule
169	        // applied via the membershipLevelCap below).
170	        boolean householdInUse = this.clinicService.isHouseholdInUse(owner.getHouseholdId(), null);
171	        if (isIdentityKeyInUse(ownerMapper.toIdentityKey(owner), null)) {
172	            throw new ResponseStatusException(HttpStatus.CONFLICT,
173	                "an owner with the same identity already exists");
174	        }
175	        int ownersInCity = countOwnersInCity(owner.getCity());
176	        if (ownersInCity >= CITY_CAPACITY) {
177	            throw new ResponseStatusException(HttpStatus.CONFLICT,
178	                "city has reached its maximum number of owners");
179	        }
180	        owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
181	        owner.setMemberId(memberIdFor(owner));
182	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
183	        owner.setHouseholdSize(countHouseholdMembers(owner.getHouseholdId()) + 1);
184	        owner.setMembershipLevelCap(householdMembershipLevelCap(owner.getHouseholdId()));
185	        owner.setBulkSignupWarning(
186	            countOwnersRegisteredOn(effectiveRegistrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
187	        // A declared household member (one created with 'sharesHousehold' that joins an existing
188	        // household) is not a suspected duplicate, so it is never flagged as a possible duplicate.
189	        boolean declaredHouseholdMember = sharesHousehold && householdInUse;
190	        Owner softDuplicate = declaredHouseholdMember ? null : findPossibleDuplicate(owner);
191	        owner.setPossibleDuplicate(softDuplicate != null);
192	        owner.setPossibleDuplicateOf(softDuplicate == null ? null : softDuplicate.getId());
193	        this.clinicService.saveOwner(owner);
194	        this.idempotencyKeyRegistry.record(idempotencyKey, owner.getId());
195	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
196	        AUDIT.info("owner created: id={} memberId={} registrationDate={} membershipLevel={}",
197	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(),
198	            ownerDto.getMembershipLevel());
199	        OwnerCreatedEvent event = OwnerCreatedEvent.of(AUDIT_EVENT_SEQUENCE.incrementAndGet(),
200	            owner.getId(), primaryIdentifier(owner), ownerDto.getMembershipLevel());
201	        AUDIT.info(event.toJson());
202	        headers.setLocation(UriComponentsBuilder.newInstance()
203	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
204	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Override
209	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
210	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
211	        if (currentOwner == null) {
212	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
213	        }
214	        currentOwner.setAddress(ownerFieldsDto.getAddress());
215	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
216	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
217	        applyAddress(currentOwner);
218	        currentOwner.setCity(ownerFieldsDto.getCity());
219	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
220	        currentOwner.setLastName(ownerFieldsDto.getLastName());
221	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
222	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
223	        this.clinicService.saveOwner(currentOwner);
224	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
225	    }
226	
227	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
228	    @Transactional
229	    @Override
230	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
231	        Owner owner = this.clinicService.findOwnerById(ownerId);
232	        if (owner == null) {
233	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
234	        }
235	        this.clinicService.deleteOwner(owner);
